llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Bumetanide, a carboxylic acid-containing loop diuretic with a butylamino side chain, showed absolute oral bioavailability of 0.79 ± 0.12 in elderly subjects, supporting high F for the query's acidic, butyl-substituted scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Bumetanide absolute bioavailability was 0.89 in normal subjects, corroborating high oral absorption for an acidic drug with lipophilic substituents.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Levodopa, a polar amino acid/carboxylic acid, had absolute oral bioavailability of 80.4% after tablet dosing, supporting high F despite ionizable polar groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Tolbutamide, a small lipophilic oral drug, had absolute oral bioavailability of 0.85, supporting high F for a moderately lipophilic acidic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Mosliciguat, a carboxylic acid-containing drug, had absolute oral bioavailability of 23.1%, which is above the 20% threshold and supports high F, albeit marginally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "6-MNA, an acidic active metabolite, had absolute oral bioavailability of approximately 35%, supporting F above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Azosemide, a thiophene-containing diuretic, had an estimated absolute oral bioavailability of approximately 20.4% in fasting healthy humans, which is at the threshold and does not affirmatively support low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Azosemide was estimated at only 10% bioavailability from urinary excretion data, but this estimate is uncertain because oral and intravenous studies were performed in different patients and serum AUCs were unavailable; it is the only affirmative low-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of highly transferable experimental evidence from acidic and lipophilic oral drugs (bumetanide, levodopa, tolbutamide, mosliciguat, 6-MNA, and others) supports F >= 20%. The only low-F analogue, azosemide, is uncertain and its absolute estimate is at the threshold, so the query is predicted high.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data are available for the query molecule.",
    "The azosemide low-F estimate is confounded by cross-study comparison and lack of serum AUC data.",
    "Potential solubility or efflux limitations arising from the two carboxylic acid groups are not directly tested in the evidence set.",
    "Food effects and formulation dependence of oral bioavailability are unknown for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

